3	import React, { useState } from 'react';
4	import { AreaTab } from './components/AreaTab';
5	import { GachaAltar } from './components/GachaAltar';
6	import { VaultGalleries } from './components/VaultGalleries';
7	import { GoldenHourConfig } from './components/GoldenHourConfig';
8	import { calculateHazardFromTime } from './store/useGoldenHourStore';
9	import { useCurrencyStore } from '../../store/useCurrencyStore';
10	import { GameLayout } from '../../components/GameLayout';
11	import { Sparkles, Users, Archive, Sliders } from 'lucide-react';
12	
13	type GoldenHourTab = 'area' | 'gacha' | 'vault' | 'config';
14	
15	export const GoldenHour: React.FC = () => {
16	  // Default: Area/Resource Config tab (replaces Arena) per Manager vision
17	  const [activeTab, setActiveTab] = useState<GoldenHourTab>('area');
18	
19	  const timeBalance = useCurrencyStore((s) => s.timeBalance);
20	  const { goldenHours, hazardLevel } = calculateHazardFromTime(timeBalance);
21	
22	  const tabs = [
23	    { id: 'area', label: 'Resource / Config', icon: <Users className="w-4 h-4" /> },
24	    { id: 'gacha', label: 'Gacha', icon: <Sparkles className="w-4 h-4" /> },
25	    { id: 'vault', label: 'Vault', icon: <Archive className="w-4 h-4" /> },
26	    { id: 'config', label: 'Config', icon: <Sliders className="w-4 h-4" /> }
27	  ];
28	
29	  return (
30	    <GameLayout
31	      gameTitle="Golden Hour"
32	      gameTitleIcon={<Sparkles />}
33	      gameTitleBadge="MASTER GAME"
34	      gameTitleSubtitle="Universal Stake Nexus • Babylonian Altar"
35	      globalInfo={{ hazardLevel, goldenHours }}
36	      tabs={tabs}
37	      activeTab={activeTab}
38	      onTabChange={(id) => setActiveTab(id as GoldenHourTab)}
39	    >
40	      {activeTab === 'area' && <AreaTab />}
41	      {activeTab === 'gacha' && <GachaAltar />}
42	      {activeTab === 'vault' && <VaultGalleries />}
43	      {activeTab === 'config' && <GoldenHourConfig />}
44	    </GameLayout>
45	  );
46	};
47	
48	export default GoldenHour;

