3	// =============================================================================
4	// [GOLDEN HOUR NEXUS — MASTER GAME TYPE DEFINITIONS]
5	// =============================================================================
6	
7	import type { GlobalRankTier } from '../../utils/rank';
8	
9	// ---------------------------------------------------------------------------
10	// ELEMENTAL ATTRIBUTES (Multi-Attribute Energy Cores / IoT Fuel)
11	// ---------------------------------------------------------------------------
12	
13	export type ElementalAttribute =
14	  | 'solar'      // Solar/Fire
15	  | 'void'       // Void/Dark
16	  | 'verdant'    // Verdant/Earth
17	  | 'celestial'  // Celestial/Light
18	  | 'aether';    // Aether/Cyber
19	
20	export interface EnergyCore {
21	  attribute: ElementalAttribute;
22	  amount: number;
23	}
24	
25	export type EnergyReserves = Record<ElementalAttribute, number>;
26	
27	// ---------------------------------------------------------------------------
28	// DIMENSIONAL TICKET TYPES (consumed in gacha)
29	// ---------------------------------------------------------------------------
30	
31	export type TicketType = 'angel-roll' | 'solar-roll' | 'codex-roll';
32	
33	export interface TicketMeta {
34	  type: TicketType;
35	  name: string;
36	  origin: string;
37	  icon: string;
38	  color: string;
39	  description: string;
40	}
41	
42	// ---------------------------------------------------------------------------
43	// GACHA RARITY TIERS
44	// ---------------------------------------------------------------------------
45	
46	export type GachaRarity = 'common' | 'uncommon' | 'rare' | 'epic' | 'legendary';
47	
48	export interface GachaRarityMeta {
49	  rarity: GachaRarity;
50	  label: string;
51	  color: string;
52	  borderColor: string;
53	  bgColor: string;
54	  weight: number; // pull probability weight
55	}
56	
57	// ---------------------------------------------------------------------------
58	// RELIC STATS & COMBAT TRAITS (for Tactical Battle Arena)
59	// ---------------------------------------------------------------------------
60	
61	export interface RelicStat {
62	  name: string;     // e.g. "ATK", "DEF", "SPD", "LUCK"
63	  value: number;    // signed — can be negative (downsides)
64	}
65	
66	export interface RelicBuff {
67	  name: string;        // e.g. "Golden Hour ×1.3", "Core Drop +20%"
68	  description: string;
69	  magnitude: number;   // multiplier or flat bonus
70	}
71	
72	export interface RelicDownside {
73	  name: string;        // e.g. "Fragile", "Cursed Drain"
74	  description: string;
75	  severity: number;    // 1-5 scale
76	}
77	
78	// ---------------------------------------------------------------------------
79	// GACHA PULL RESULT ITEM (what you get from a card pack)
80	// ---------------------------------------------------------------------------
81	
82	export type PullItemCategory = 'relic' | 'collectible' | 'energy-core';
83	
84	export interface PullItem {
85	  id: string;
86	  name: string;
87	  description: string;
88	  category: PullItemCategory;
89	  rarity: GachaRarity;
90	  rank: GlobalRankTier;
91	  score: number;               // hazard score for rank calculation
92	  origin: TicketType;          // which dimension this came from
93	  iconEmoji: string;
94	
95	  // Relic-specific (combat equipment for Tab 1)
96	  stats?: RelicStat[];
97	  buffs?: RelicBuff[];
98	  downsides?: RelicDownside[];
99	
100	  // Energy Core specific (IoT fuel filler)
101	  energyCores?: EnergyCore[];
102	
103	  // Collectible specific (pure display)
104	  loreText?: string;
105	  seriesName?: string;
106	
107	  pulledAt: string;            // ISO timestamp
108	}
109	
110	// ---------------------------------------------------------------------------
111	// VAULT COLLECTION (Tab 3 — sorted by purpose)
112	// ---------------------------------------------------------------------------
113	
114	export type VaultCategory = 'tactical' | 'collection' | 'energy';
115	
116	// ---------------------------------------------------------------------------
117	// GACHA CARD PACK DEFINITION
118	// ---------------------------------------------------------------------------
119	
120	export interface CardPack {
121	  id: string;
122	  name: string;
123	  description: string;
124	  ticketType: TicketType;
125	  ticketCost: number;
126	  color: string;
127	  iconEmoji: string;
128	  poolItems: PullItem[];      // pool of possible items (template, without pulledAt)
129	}
130	
131	// ---------------------------------------------------------------------------
132	// GOLDEN HOURS & HAZARD LEVEL
133	// ---------------------------------------------------------------------------
134	
135	export interface HazardProfile {
136	  goldenHours: number;         // accumulated lifetime productive hours
137	  hazardLevel: number;         // f(x) = 1.5 * ln(x + 1), clamped >= 0
138	}
139	
140	// ---------------------------------------------------------------------------
141	// BATTLE ARENA STATE (Tab 1 — Babylonian Altar Loadout)
142	// ---------------------------------------------------------------------------
143	
144	export interface ArenaSlot {
145	  slotIndex: number;           // 0-3 (4 equipment slots)
146	  equippedItem: PullItem | null;
147	}
148	
149	// ---------------------------------------------------------------------------
150	// STORE STATE SHAPE
151	// ---------------------------------------------------------------------------
152	
153	export interface GoldenHourState {
154	  // Vault — all pulled items
155	  vault: PullItem[];
156	
157	  // Hazard Profile
158	  hazardProfile: HazardProfile;
159	
160	  // Energy Reserves (IoT fuel)
161	  energyReserves: EnergyReserves;
162	
163	  // Battle Arena slots
164	  arenaSlots: ArenaSlot[];
165	
166	  // Pull history count
167	  totalPulls: number;
168	
169	  // Actions
170	  pullFromPack: (ticketType: TicketType) => PullItem | null;
171	  equipRelic: (slotIndex: number, itemId: string) => void;
172	  unequipRelic: (slotIndex: number) => void;
173	  addGoldenHours: (hours: number) => void;
174	  consumeEnergy: (attribute: ElementalAttribute, amount: number) => boolean;
175	  getVaultByCategory: (category: VaultCategory) => PullItem[];
176	
177	  // Developer / Sandbox Cheat Actions
178	  injectSampleRelics: () => void;
179	  injectEnergyReserves: (attribute: ElementalAttribute, amount: number) => void;
180	  clearVault: () => void;
181	  resetEnergyReserves: () => void;
182	}
