3	import { create } from 'zustand';
4	import type {
5	  GoldenHourState,
6	  PullItem,
7	  TicketType,
8	  ElementalAttribute,
9	  GachaRarity,
10	  VaultCategory,
11	  GachaRarityMeta,
12	  TicketMeta,
13	} from '../types';
14	import { useInventoryStore } from '../../../store/useInventoryStore';
15	import { persistVault, logAuditEvent } from '../../../core/syncEngine';
16	
17	// =============================================================================
18	// HAZARD LEVEL MATHEMATICAL FORMULA
19	// hazard = ln(x + 1), where x is golden hours (timeSeconds / 3600, clamped >= 0)
20	// =============================================================================
21	
22	export function calculateHazardLevel(goldenHours: number): number {
23	  if (goldenHours < 0) return 0;
24	  return Math.round(Math.log(goldenHours + 1) * 100) / 100;
25	}
26	
27	export function calculateHazardFromTime(timeBalanceSeconds: number): { timeSeconds: number; goldenHours: number; hazardLevel: number } {
28	  const timeSeconds = Math.max(0, timeBalanceSeconds);
29	  const goldenHours = timeSeconds / 3600;
30	  const hazardLevel = calculateHazardLevel(goldenHours);
31	  return { timeSeconds, goldenHours, hazardLevel };
32	}
33	
34	// =============================================================================
35	// RARITY METADATA & PROBABILITY WEIGHTS
36	// =============================================================================
37	
38	export const RARITY_TABLE: Record<GachaRarity, GachaRarityMeta> = {
