81	// =============================================================================
82	// TICKET REGISTRY
83	// =============================================================================
84	
85	export const TICKET_REGISTRY: Record<TicketType, TicketMeta> = {
86	  'angel-roll': {
87	    type: 'angel-roll',
88	    name: 'Angel Roll Ticket',
89	    origin: 'Vinyl Angel (Harmonic Lab)',
90	    icon: '🎟️',
91	    color: '#ffd86b',
92	    description: 'Earned by generating tracks, training neural audio weights, or mastering records.',
93	  },
94	  'solar-roll': {
95	    type: 'solar-roll',
96	    name: 'Solar Roll Ticket',
97	    origin: 'Farm Alpha / Beta (Bio-Agrarian)',
98	    icon: '☀️',
99	    color: '#f97316',
100	    description: 'Harvested from solar crops and agrarian yield contracts.',
101	  },
