112	// =============================================================================
113	// ELEMENTAL ATTRIBUTE DEFINITIONS
114	// =============================================================================
115	
116	export const ELEMENT_REGISTRY: Record<ElementalAttribute, { name: string; color: string; icon: string }> = {
117	  solar: { name: 'Solar Thermal', color: '#f97316', icon: '☀️' },
118	  void: { name: 'Void Kinetic', color: '#a855f7', icon: '🌌' },
119	  verdant: { name: 'Verdant Bio', color: '#22c55e', icon: '🌿' },
120	  celestial: { name: 'Celestial Astral', color: '#ffd86b', icon: '✨' },
121	  aether: { name: 'Aether Cyber', color: '#38bdf8', icon: '⚡' },
122	};
123	
124	// =============================================================================
125	// PROCEDURAL ITEM GENERATION TEMPLATES
126	// =============================================================================
127	
128	const SAMPLE_RELIC_PREFIXES = [
129	  'Babylonian', 'Celestial', 'Abyssal', 'Aetheric', 'Sunforged', 'Resonant', 'Hyperborean', 'Elysian', 'Voidbound', 'Chronos'
130	];
131	
132	const SAMPLE_RELIC_NOUNS = [
133	  'Blade', 'Aegis', 'Scepter', 'Harmonica', 'Gauntlet', 'Pendant', 'Hourglass', 'Codex', 'Crucible', 'Prism'
134	];
135	
136	const SAMPLE_COLLECTIBLES = [
137	  { name: 'Enuma Elish Tablet Fragment', series: 'Ancient Mesopotamia', lore: 'When on high the heaven was not named, and the earth beneath yet bare no name...' },
138	  { name: 'First Edition Vinyl: Angelic Sine Waves', series: 'Harmonic Archives', lore: 'Mastered in the 432Hz harmonic chamber during the 2026 Solstice.' },
139	  { name: 'Bio-Magnetic Agrarian Core', series: 'Solar Agrarian', lore: 'A pulsating chlorophyll battery capable of sustaining miniature biosensors.' },
140	  { name: 'Zero-Point Matrix Crystal', series: 'Aetheric Physics', lore: 'Refracts multidimensional light into raw electrical potential.' },
141	];
142	
143	function generateRandomItem(ticketType: TicketType): PullItem {
144	  // 1. Roll Rarity
145	  const roll = Math.random() * 100;
146	  let accumulated = 0;
147	  let chosenRarity: GachaRarity = 'common';
148	
149	  for (const r of Object.values(RARITY_TABLE)) {
150	    accumulated += r.weight;
151	    if (roll <= accumulated) {
152	      chosenRarity = r.rarity;
153	      break;
154	    }
155	  }
156	
157	  const categoryRoll = Math.random();
158	  const id = `item_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
159	
160	  // Category 1: Relic (45% chance)
161	  if (categoryRoll < 0.45) {
162	    const prefix = SAMPLE_RELIC_PREFIXES[Math.floor(Math.random() * SAMPLE_RELIC_PREFIXES.length)];
163	    const noun = SAMPLE_RELIC_NOUNS[Math.floor(Math.random() * SAMPLE_RELIC_NOUNS.length)];
164	    const name = `${prefix} ${noun}`;
165	
166	    const scoreMultiplier = { common: 2.0, uncommon: 4.0, rare: 6.0, epic: 8.0, legendary: 10.0 }[chosenRarity];
167	    const score = Math.round((Math.random() * 2.0 + scoreMultiplier) * 100) / 100;
168	
169	    const rank = chosenRarity === 'legendary' ? '✦'
170	      : chosenRarity === 'epic' ? 'Ψ'
171	      : chosenRarity === 'rare' ? 'S₁'
172	      : chosenRarity === 'uncommon' ? 'A+'
173	      : 'B';
174	
175	    const atk = Math.floor(Math.random() * 15 * scoreMultiplier);
176	    const def = Math.floor(Math.random() * 12 * scoreMultiplier);
177	    const spd = Math.floor(Math.random() * 10 * scoreMultiplier);
178	    const luck = Math.floor(Math.random() * 8 * scoreMultiplier);
179	
180	    const downsideSeverity = Math.floor(Math.random() * 3) + 1;
181	    const downsidePenalty = downsideSeverity * 3;
182	
183	    return {
184	      id,
185	      name,
186	      description: `Double-edged ancient armament summoned from the ${TICKET_REGISTRY[ticketType].name}. Bestows tremendous power with a binding penalty.`,
187	      category: 'relic',
188	      rarity: chosenRarity,
189	      rank,
190	      score,
191	      origin: ticketType,
192	      iconEmoji: '⚔️',
193	      stats: [
194	        { name: 'ATK', value: atk },
195	        { name: 'DEF', value: def },
196	        { name: 'SPD', value: spd - downsidePenalty },
197	        { name: 'LUCK', value: luck },
198	      ],
199	      buffs: [
200	        {
201	          name: `${prefix} Resonance`,
202	          description: `Boosts Golden Hour yield multiplier by +${(scoreMultiplier * 2.5).toFixed(1)}%.`,
203	          magnitude: scoreMultiplier * 0.025,
204	        },
205	      ],
206	      downsides: [
207	        {
208	          name: `Curse of ${prefix}`,
209	          description: `Reduces combat movement speed by -${downsidePenalty} and increases stamina drain.`,
210	          severity: downsideSeverity,
211	        },
212	      ],
213	      pulledAt: new Date().toISOString(),
214	    };
215	  }
216	
217	  // Category 2: Collectible (30% chance)
218	  if (categoryRoll < 0.75) {
219	    const template = SAMPLE_COLLECTIBLES[Math.floor(Math.random() * SAMPLE_COLLECTIBLES.length)];
220	    const scoreMultiplier = { common: 1.5, uncommon: 3.5, rare: 5.5, epic: 7.5, legendary: 9.5 }[chosenRarity];
221	    const score = Math.round((Math.random() * 1.5 + scoreMultiplier) * 100) / 100;
222	
223	    const rank = chosenRarity === 'legendary' ? 'Ø'
224	      : chosenRarity === 'epic' ? 'Ψ'
225	      : chosenRarity === 'rare' ? 'S₂'
226	      : chosenRarity === 'uncommon' ? 'A'
227	      : 'C';
228	
229	    return {
230	      id,
231	      name: template.name,
232	      description: `Historical archival relic representing milestone achievements across dimensional worlds.`,
233	      category: 'collectible',
234	      rarity: chosenRarity,
235	      rank,
236	      score,
237	      origin: ticketType,
238	      iconEmoji: '🏺',
239	      seriesName: template.series,
240	      loreText: template.lore,
241	      pulledAt: new Date().toISOString(),
242	    };
243	  }
244	
245	  // Category 3: Multi-Attribute Energy Cores (IoT Fuel - 25% chance)
246	  const elements: ElementalAttribute[] = ['solar', 'void', 'verdant', 'celestial', 'aether'];
247	  const element = elements[Math.floor(Math.random() * elements.length)];
248	  const amount = Math.floor(Math.random() * 5 + 1) * 10;
249	
250	  return {
251	    id,
252	    name: `${ELEMENT_REGISTRY[element].name} Energy Core (${amount}u)`,
253	    description: `Multi-attribute IoT fuel cell. Used to power real-world sensory telemetry and fitness gear.`,
254	    category: 'energy-core',
255	    rarity: chosenRarity,
256	    rank: 'D',
257	    score: 1.2,
258	    origin: ticketType,
259	    iconEmoji: '⚡',
260	    energyCores: [{ attribute: element, amount }],
261	    pulledAt: new Date().toISOString(),
262	  };
263	}
264	
265	function syncVaultToBackend(get: () => GoldenHourState) {
266	  const current = get();
267	  persistVault({
268	    vault: current.vault,
269	    arenaSlots: current.arenaSlots,
270	    energyReserves: current.energyReserves,
271	    totalPulls: current.totalPulls,
272	  }).catch((err) => {
273	    console.error('[GoldenHourStore] Failed to persist vault to backend:', err);
274	  });
275	}
276	
277	// =============================================================================
278	// ZUSTAND STORE IMPLEMENTATION
279	// =============================================================================
280	
281	export const useGoldenHourStore = create<GoldenHourState>()(
282	  (set, get) => ({
283	    vault: [],
284	    hazardProfile: {
285	      goldenHours: 0,
286	      hazardLevel: 0,
287	    },
288	    energyReserves: {
289	      solar: 120,
290	      void: 50,
291	      verdant: 80,
292	      celestial: 30,
293	      aether: 65,
294	    },
295	    arenaSlots: [
296	      { slotIndex: 0, equippedItem: null },
297	      { slotIndex: 1, equippedItem: null },
298	      { slotIndex: 2, equippedItem: null },
299	      { slotIndex: 3, equippedItem: null },
300	    ],
301	    totalPulls: 0,
302	
303	    // -----------------------------------------------------------------------
304	    // PULL FROM PACK (Single Roll)
305	    // -----------------------------------------------------------------------
306	    pullFromPack: (ticketType: TicketType) => {
307	      const inv = useInventoryStore.getState();
308	
309	      // 1. Check ticket availability and consume
310	      let hasTicket = false;
311	      if (ticketType === 'angel-roll' && inv.angelRollTickets >= 1) {
312	        inv.spendAngelTickets(1);
313	        hasTicket = true;
314	      } else if (ticketType === 'solar-roll' && inv.solarRollTickets >= 1) {
315	        inv.spendSolarTickets(1);
316	        hasTicket = true;
317	      } else if (ticketType === 'codex-roll' && inv.codexRollTickets >= 1) {
318	        inv.spendCodexTickets(1);
319	        hasTicket = true;
320	      }
321	
322	      if (!hasTicket) {
323	        return null;
324	      }
325	
326	      // 2. Generate item
327	      const item = generateRandomItem(ticketType);
328	
329	      // 3. If energy core, auto-inject into energy reserves
330	      let newReserves = { ...get().energyReserves };
331	      if (item.category === 'energy-core' && item.energyCores) {
332	        for (const core of item.energyCores) {
333	          newReserves[core.attribute] = (newReserves[core.attribute] || 0) + core.amount;
334	        }
335	      }
336	
337	      // 4. Update store state
338	      set((state) => ({
339	        vault: [item, ...state.vault],
340	        energyReserves: newReserves,
341	        totalPulls: state.totalPulls + 1,
342	      }));
343	
344	      // 5. Persist to backend and log audit event
345	      syncVaultToBackend(get);
346	      logAuditEvent('GACHA_PULL', {
347	        ticketType,
348	        itemId: item.id,
349	        itemName: item.name,
350	        category: item.category,
351	        rarity: item.rarity,
352	        rank: item.rank,
353	      });
354	
355	      return item;
356	    },
357	
358	    // -----------------------------------------------------------------------
359	    // ARENA EQUIPMENT ACTIONS
360	    // -----------------------------------------------------------------------
361	    equipRelic: (slotIndex: number, itemId: string) => {
362	      const item = get().vault.find((i) => i.id === itemId);
363	      if (!item || item.category !== 'relic') return;
364	
365	      set((state) => {
366	        const newSlots = state.arenaSlots.map((slot) => {
367	          if (slot.equippedItem?.id === itemId && slot.slotIndex !== slotIndex) {
368	            return { ...slot, equippedItem: null };
369	          }
370	          if (slot.slotIndex === slotIndex) {
371	            return { ...slot, equippedItem: item };
372	          }
373	          return slot;
374	        });
375	        return { arenaSlots: newSlots };
376	      });
377	
378	      syncVaultToBackend(get);
379	      logAuditEvent('RELIC_EQUIPPED', { slotIndex, itemId, relicName: item.name });
380	    },
381	
382	    unequipRelic: (slotIndex: number) => {
383	      set((state) => ({
384	        arenaSlots: state.arenaSlots.map((s) =>
385	          s.slotIndex === slotIndex ? { ...s, equippedItem: null } : s
386	        ),
387	      }));
388	
389	      syncVaultToBackend(get);
390	      logAuditEvent('RELIC_UNEQUIPPED', { slotIndex });
391	    },
392	
393	    // -----------------------------------------------------------------------
394	    // GOLDEN HOURS & HAZARD LEVEL
395	    // -----------------------------------------------------------------------
